class Solution:
    def search(self, nums: list[int], target: int) -> int:
        lo, hi = 0, len(nums) - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            if nums[mid] == target:  # viz:check
                return mid  # viz:found
            if nums[mid] < target:
                lo = mid + 1  # viz:go_right
            else:
                hi = mid - 1  # viz:go_left
        return -1  # viz:missing

class Solution:
    def dailyTemperatures(self, temperatures: list[int]) -> list[int]:
        answer = [0] * len(temperatures)
        stack: list[int] = []
        for i, t in enumerate(temperatures):
            while stack and temperatures[stack[-1]] < t:  # viz:compare
                j = stack.pop()  # viz:resolve
                answer[j] = i - j
            stack.append(i)  # viz:push
        return answer  # viz:done

class Solution:
    def groupAnagrams(self, strs: list[str]) -> list[list[str]]:
        groups = defaultdict(list)  # viz:setup
        for word in strs:
            key = "".join(sorted(word))  # viz:sort
            groups[key].append(word)  # viz:add
        return list(groups.values())  # viz:done

class MinStack:
    def __init__(self):
        self.vals: list[int] = []
        self.mins: list[int] = []  # mins[i] is the smallest of vals[0], ..., vals[i]

    def push(self, val: int) -> None:
        vals, mins = self.vals, self.mins
        low = val if not mins else min(val, mins[-1])  # viz:compare
        vals.append(val)  # viz:push
        mins.append(low)

    def pop(self) -> None:
        vals, mins = self.vals, self.mins
        vals.pop()  # viz:pop
        mins.pop()

    def top(self) -> int:
        vals = self.vals
        return vals[-1]  # viz:top

    def getMin(self) -> int:
        mins = self.mins
        return mins[-1]  # viz:min

class Solution:
    def twoSum(self, nums: list[int], target: int) -> list[int]:
        seen: dict[int, int] = {}
        for i, x in enumerate(nums):
            partner = target - x
            if partner in seen:  # viz:check
                return [seen[partner], i]  # viz:found
            seen[x] = i  # viz:store
        return []

class Solution:
    def isPalindrome(self, s: str) -> bool:
        l, r = 0, len(s) - 1
        while l < r:
            if not s[l].isalnum():
                l += 1  # viz:skip_l
            elif not s[r].isalnum():
                r -= 1  # viz:skip_r
            elif s[l].lower() != s[r].lower():  # viz:compare
                return False  # viz:mismatch
            else:
                l += 1  # viz:match
                r -= 1
        return True  # viz:done
